compiledVertexShaders:
#version 300 es
precision highp float;
in vec3 aVertexPosition;
in vec2 aTextureCoord;
uniform mat4 uMVMatrix;
uniform mat4 uPMatrix;
out vec2 vTextureCoord;
void main() {
  gl_Position = uPMatrix * uMVMatrix * vec4(aVertexPosition, 1.0);
  vTextureCoord = aTextureCoord;
}

compiledFragmentShaders:
#version 300 es
precision mediump float;
in vec2 vTextureCoord;
out vec4 fragColor;
uniform vec2 uResolution;
uniform vec2 uMousePos;
uniform float uTime;
uniform float uClick;
uniform float uIntensity;
uniform float uDistortion;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uBg;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

// Fast analytic trigonometric curl flow — silky 60fps even on integrated GPUs
vec2 warpField(vec2 p, float t, float d) {
  vec2 w = p;
  w += 0.34 * d * vec2(sin(w.y * 2.4 + t * 0.85), cos(w.x * 2.2 - t * 0.72));
  w += 0.22 * d * vec2(cos(w.y * 3.9 - t * 1.15 + w.x * 1.4), sin(w.x * 3.6 + t * 0.95 - w.y * 1.2));
  w += 0.11 * d * vec2(sin(w.x * 6.2 + w.y * 4.5 + t * 1.3), cos(w.y * 5.8 - w.x * 4.1 - t * 1.1));
  return w;
}

void main() {
  vec2 uv = vTextureCoord;
  vec2 asp = vec2(uResolution.x / max(1.0, uResolution.y), 1.0);
  vec2 p = (uv - 0.5) * asp;
  vec2 m = (uMousePos - 0.5) * asp;
  float t = uTime * 0.028;

  // Interactive cursor gravity pull + click chromatic shockwave
  vec2 toM = p - m;
  float dM = length(toM);
  float pull = exp(-dM * 2.5) * (0.32 + 0.22 * uClick) * uDistortion;
  float shock = exp(-pow(abs(dM - (0.16 + 0.26 * uClick)), 2.0) * 85.0) * uClick;
  vec2 wp = p - normalize(toM + 0.0001) * pull * 0.36;

  vec2 w = warpField(wp * 1.15, t, uDistortion);
  float ridgeA = pow(0.5 + 0.5 * sin(w.x * 3.1 + w.y * 2.2 - t * 0.6), 2.4);
  float ridgeB = pow(0.5 + 0.5 * cos(w.y * 3.4 - w.x * 2.5 + t * 0.55), 2.8);
  float silk = pow(max(0.0, 1.0 - abs(sin(w.x * 2.6 + w.y * 1.9)) * 1.7), 2.6);

  float orb1 = exp(-length(p - vec2(0.46 + 0.14 * sin(t * 0.65), 0.18 + 0.10 * cos(t * 0.55))) * 1.45);
  float orb2 = exp(-length(p - vec2(-0.42 + 0.14 * cos(t * 0.5), -0.18 + 0.12 * sin(t * 0.6))) * 1.55);
  float mGlow = exp(-dM * 2.6) * (0.7 + 0.35 * uClick);

  float bgLum = dot(uBg, vec3(0.299, 0.587, 0.114));
  vec3 col = uBg;

  if (bgLum > 0.5) {
    col = mix(col, uColorA, clamp((orb1 * 0.45 + ridgeA * 0.32) * uIntensity, 0.0, 0.7));
    col = mix(col, uColorB, clamp((orb2 * 0.42 + ridgeB * 0.3 + mGlow * 0.38) * uIntensity, 0.0, 0.65));
    col = mix(col, vec3(1.0), silk * 0.38);
  } else {
    col = mix(col, mix(uBg, uColorA, 0.68), clamp((orb1 * 0.8 + ridgeA * 0.46) * uIntensity, 0.0, 0.92));
    col += uColorA * (silk * 0.58 + ridgeA * 0.24) * uIntensity;
    col += uColorB * (ridgeB * 0.52 + orb2 * 0.45 + mGlow * 0.48 + shock * 0.6) * uIntensity;
    col += mix(mix(uColorA, uColorB, ridgeA), vec3(1.0), 0.4) * silk * ridgeB * 0.95 * uIntensity;
    float vig = smoothstep(1.38, 0.25, length(p * vec2(0.84, 1.04)));
    col *= mix(0.64, 1.06, vig);
  }

  col += (hash(gl_FragCoord.xy + fract(t * 17.3)) - 0.5) * 0.014;
  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
